+/** Convert a string into a lowercase URL-safe slug. */
+export function slugify(value) {
+  if (typeof value !== "string") throw new TypeError("slugify expects a string");
+
+  return value
+    .toLowerCase()
+    .trim()
+    .replace(/[^a-z0-9]+/g, "-")
+    .replace(/^-+|-+$/g, "");
+}
