+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { slugify } from "../src/slugify.js";
+
+test("slugify creates lowercase URL-safe slugs", () => {
+  assert.equal(slugify("Hello, World!"), "hello-world");
+  assert.equal(slugify("  Multiple --- separators  "), "multiple-separators");
+});
+
+test("slugify returns an empty slug for empty input", () => {
+  assert.equal(slugify(""), "");
+});
+
+test("slugify rejects non-string input", () => {
+  assert.throws(() => slugify(1), TypeError);
+});
